SELECT COUNT(*) FROM task WHERE
STATUS = #{key} AND
YEARWEEK(StartTime, 1) = YEARWEEK(CURDATE(), 1);

SELECT COUNT(*) FROM task WHERE
STATUS = #{key} AND
DATE_FORMAT(StartTime, '%Y-%m') = DATE_FORMAT(CURDATE(), '%Y-%m');

SELECT COUNT(*)
FROM task
WHERE STATUS = 'COMPLETED' and OwnerId = #{id}

SELECT COUNT(*)
FROM task
WHERE STATUS = 'EXPIRED' and OwnerId = #{id}

SELECT COUNT(*)
FROM task
WHERE STATUS = 'CANCELLED' and OwnerId = #{id}

SELECT STATUS
FROM task
WHERE TaskID = #{id}

SELECT t.*, u.CreditScore AS ownerCredit FROM task t LEFT JOIN users u ON t.OwnerID = u.UserID
AND t.STATUS = #{statusDb}
AND t.STATUS IN ('ACCEPTED','ONGOING','COMPLETED')
AND t.TaskType = #{taskTypeId}
AND t.Location = #{location}
AND t.Description LIKE CONCAT('%', #{description}, '%')
ORDER BY u.CreditScore DESC,
t.StartTime ASC t.StartTime DESC , t.TaskID DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM task t



			AND t.STATUS = #{statusDb}


			AND t.STATUS IN ('ACCEPTED','ONGOING','COMPLETED')



		AND t.TaskType = #{taskTypeId}


		AND t.Location = #{location}


		AND t.Description LIKE CONCAT('%', #{description}, '%')
